item.stdout:
My Bookmarks

Save a link — the page details get filled in for you.

Paste a link to save
Save
Tip: try one of your own links, or the example we suggested.

SAVED

Nothing saved yet. Paste a link above and press Save to see it appear here.<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>My Bookmarks — prototype</title>
<style>
  :root {
    --bg: #f5f6f8;
    --card: #ffffff;
    --ink: #1c2333;
    --muted: #6b7280;
    --line: #e5e7eb;
    --accent: #2f6df6;
    --accent-ink: #ffffff;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--ink);
    line-height: 1.45;
  }
  header {
    padding: 22px 20px 10px;
    max-width: 760px;
    margin: 0 auto;
  }
  header h1 { margin: 0; font-size: 22px; }
  header p { margin: 4px 0 0; color: var(--muted); font-size: 14px; }
  main { max-width: 760px; margin: 0 auto; padding: 0 20px 60px; }

  .saver {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 16px;
    margin: 16px 0 26px;
    box-shadow: 0 1px 2px rgba(0,0,0,0.03);
  }
  .saver label { font-size: 13px; color: var(--muted); display: block; margin-bottom: 6px; }
  .saver-row { display: flex; gap: 8px; }
  .saver input[type="url"] {
    flex: 1;
    padding: 11px 12px;
    font-size: 15px;
    border: 1px solid var(--line);
    border-radius: 8px;
    outline: none;
  }
  .saver input[type="url"]:focus { border-color: var(--accent); }
  .btn {
    border: none;
    background: var(--accent);
    color: var(--accent-ink);
    font-size: 15px;
    font-weight: 600;
    padding: 11px 18px;
    border-radius: 8px;
    cursor: pointer;
    white-space: nowrap;
  }
  .btn:disabled { opacity: .55; cursor: default; }
  .hint { font-size: 12px; color: var(--muted); margin-top: 8px; }

  .section-title { font-size: 13px; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); margin: 0 0 12px; }

  .empty {
    text-align: center;
    color: var(--muted);
    padding: 40px 20px;
    border: 1px dashed var(--line);
    border-radius: 12px;
    background: #fafbfc;
  }

  .card {
    display: flex;
    gap: 14px;
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 14px;
    margin-bottom: 12px;
    box-shadow: 0 1px 2px rgba(0,0,0,0.03);
    animation: pop .25s ease;
  }
  @keyframes pop { from { transform: translateY(6px); opacity: 0; } to { transform: none; opacity: 1; } }
  .thumb {
    width: 96px; height: 72px; flex: none;
    border-radius: 8px; background: #eef1f6;
    display: flex; align-items: center; justify-content: center;
    font-size: 26px; color: #97a3b6; overflow: hidden;
  }
  .thumb img { width: 100%; height: 100%; object-fit: cover; }
  .card-body { flex: 1; min-width: 0; }
  .card-title { font-size: 16px; font-weight: 600; margin: 0 0 3px; }
  .card-site { font-size: 12px; color: var(--muted); display: flex; align-items: center; gap: 6px; margin-bottom: 6px; }
  .card-site .fav { width: 14px; height: 14px; border-radius: 3px; }
  .card-desc { font-size: 14px; color: #384152; margin: 0 0 8px; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
  .card-url { font-size: 12px; color: var(--accent); word-break: break-all; }
  .card-meta { font-size: 12px; color: var(--muted); margin-top: 8px; }

  .loading .thumb { animation: pulse 1.1s infinite; }
  .skeleton { background: linear-gradient(90deg,#eef1f6,#f6f8fb,#eef1f6); border-radius: 6px; height: 12px; margin-bottom: 8px; }
  .skeleton.w70 { width: 70%; } .skeleton.w40 { width: 40%; } .skeleton.w90 { width: 90%; }
  @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:.55} }

  @media (max-width: 520px) {
    .saver-row { flex-direction: column; }
    .thumb { width: 72px; height: 56px; }
  }
</style>
</head>
<body>
<header>
  <h1>My Bookmarks</h1>
  <p>Save a link — the page details get filled in for you.</p>
</header>
<main>
  <div class="saver">
    <label for="url">Paste a link to save</label>
    <div class="saver-row">
      <input id="url" type="url" placeholder="https://…" autocomplete="off" />
      <button id="saveBtn" class="btn">Save</button>
    </div>
    <div class="hint">Tip: try one of your own links, or the example we suggested.</div>
  </div>

  <p class="section-title">Saved</p>
  <div id="list"></div>
  <div id="empty" class="empty">
    Nothing saved yet. Paste a link above and press <strong>Save</strong> to see it appear here.
  </div>
</main>

<script>
// --- Simulated page-detail lookup (prototype only) ---
// Stands in for automatically reading a page's title/site/description.
const KNOWN = {
  "nasa.gov/webb": {
    title: "NASA's James Webb Space Telescope",
    site: "nasa.gov",
    desc: "The largest, most powerful space telescope ever built, revealing the universe in infrared light — from the earliest galaxies to exoplanet atmospheres.",
    emoji: "🔭"
  },
  "developer.mozilla.org/css-grid": {
    title: "CSS Grid Layout — MDN Web Docs",
    site: "developer.mozilla.org",
    desc: "A complete guide to CSS Grid: rows, columns, areas, and alignment, with examples and browser support notes.",
    emoji: "📘"
  },
  "recipes.example.com/ramen": {
    title: "Rich Tonkotsu Ramen from Scratch",
    site: "recipes.example.com",
    desc: "A weekend project: 12-hour pork bone broth, homemade tare, and springy noodles. Step-by-step with photos.",
    emoji: "🍜"
  }
};

function lookup(url) {
  let clean = url.replace(/^https?:\/\//i, "").replace(/^www\./i, "").replace(/\/+$/,"");
  for (const key in KNOWN) {
    if (clean.toLowerCase().startsWith(key.toLowerCase())) {
      return { ...KNOWN[key], url };
    }
  }
  // Fallback: derive a readable title/site from the URL itself.
  let host = clean.split("/")[0];
  let path = clean.split("/").slice(1).join("/");
  let guessTitle = path
    ? decodeURIComponent(path.split(/[/?#]/)[0]).replace(/[-_]+/g," ").replace(/\.\w+$/,"").trim()
    : host;
  guessTitle = guessTitle ? guessTitle.replace(/\b\w/g, c => c.toUpperCase()) : host;
  return {
    title: guessTitle || host,
    site: host,
    desc: "",
    emoji: "🔖",
    url
  };
}

const listEl = document.getElementById("list");
const emptyEl = document.getElementById("empty");
const input = document.getElementById("url");
const btn = document.getElementById("saveBtn");

function refreshEmpty() {
  emptyEl.style.display = listEl.children.length ? "none" : "block";
}

function timeLabel() {
  const d = new Date();
  return "Saved just now · " + d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
}

function save() {
  const url = input.value.trim();
  if (!url) { input.focus(); return; }

  btn.disabled = true;
  // Insert a loading card first (simulates fetching details).
  const card = document.createElement("div");
  card.className = "card loading";
  card.innerHTML = `
    <div class="thumb">⏳</div>
    <div class="card-body">
      <div class="skeleton w70"></div>
      <div class="skeleton w40"></div>
      <div class="skeleton w90"></div>
    </div>`;
  listEl.prepend(card);
  refreshEmpty();

  setTimeout(() => {
    const m = lookup(url);
    card.className = "card";
    card.innerHTML = `
      <div class="thumb">${m.emoji || "🔖"}</div>
      <div class="card-body">
        <div class="card-title">${escapeHtml(m.title)}</div>
        <div class="card-site"><span>🌐</span>${escapeHtml(m.site)}</div>
        ${m.desc ? `<p class="card-desc">${escapeHtml(m.desc)}</p>` : ""}
        <div class="card-url">${escapeHtml(m.url)}</div>
        <div class="card-meta">${timeLabel()}</div>
      </div>`;
    input.value = "";
    btn.disabled = false;
    input.focus();
  }, 850);
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));
}

btn.addEventListener("click", save);
input.addEventListener("keydown", e => { if (e.key === "Enter") save(); });

refreshEmpty();
document.body.setAttribute("data-harness-ready", "true");
</script>
</body>
</html>

